  function rowsFor(cfg=page){return data[cfg.entity]||[];}
  function groupName(cfg=page){return cfg.admin?'관리자 · '+cfg.group:cfg.group;}
  function badge(value,context=''){return window.CRMStatus.render(value,context);}
  function control(field,value='',prefix='f'){
    const id=prefix+'-'+field.key;const attrs=`id="${esc(id)}" name="${esc(field.key)}" ${field.required?'required':''}`;
    let choices=field.options||[];
    if(field.key==='company'&&(field.type==='select'||field.type==='multi'))choices=['선택하세요',...data.customers.map(c=>c.name)];
    if(field.type==='select')return `<select ${attrs}>${choices.map(o=>`<option value="${o==='전체'||o==='선택하세요'?'':esc(o)}" ${(value===o||(!value&&o==='전체'))?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
    if(field.type==='textarea')return `<textarea ${attrs} placeholder="내용을 입력하세요">${esc(value)}</textarea>`;
    if(field.type==='checkbox')return `<input ${attrs} type="checkbox" ${value?'checked':''}>`;
    if(field.type==='file')return `<input ${attrs} type="file" multiple>`;
    if(field.type==='multi'){const selected=Array.isArray(value)?value:value?[value]:[];return `<div class="multi-field"><details><summary><span>${selected.length?esc(selected.join(', ')):'품목을 선택하세요'}</span>${icon('chevron')}</summary><div class="multi-options">${choices.map(o=>`<label><input type="checkbox" name="${esc(field.key)}" value="${esc(o)}" ${selected.includes(o)?'checked':''}>${esc(o)}</label>`).join('')}</div></details></div>`;}
    if(field.type==='line-items')return lineItems(value);
    const min=field.type==='number'?'min="0"':'';const max=field.key==='score'?'max="100"':'';
    return `<input ${attrs} type="${field.type||'text'}" value="${esc(value)}" ${min} ${max} placeholder="${esc(field.label)}">`;
  }
  function fieldMarkup(field,value,prefix='field'){const full=['textarea','line-items','file'].includes(field.type);const tag=['multi','line-items'].includes(field.type)?'div':'label';return `<${tag} class="form-field ${full?'full':''}" ${field.type==='multi'?'aria-label="'+esc(field.label)+'"':''}>${esc(field.label)}${field.required?' <span class="required-star">*</span>':''}${control(field,value,prefix)}</${tag}>`;}
  function pageHeader(actions=''){return `<div class="page-head ${page.id==='home'?'dashboard-head':''}"><div><span class="eyebrow">${esc(page.admin?'ADMINISTRATION':'IONE WORKSPACE')} ${page.proposed?'· PROPOSAL':''}</span><h1>${esc(page.title)}</h1><p>${esc(page.description)}</p></div>${page.id==='home'?dashboardDepth():''}<div class="page-actions">${page.proposed?'<span class="proposal-badge">제안 시안</span>':''}${actions}</div></div>`;}
  function dashboardDepth(){return `<div class="dashboard-depth" aria-hidden="true"><div class="depth-sheet back"></div><div class="depth-sheet front"><div class="depth-line"></div><div class="depth-line short"></div><div class="depth-bars"><i></i><i></i><i></i></div></div><div class="depth-check">${icon('check')}</div></div>`;}
  function button(text,action,style='',ico=''){return `<button type="button" class="suite-button ${style}" data-action="${action}">${ico?icon(ico):''}${esc(text)}</button>`;}
  function filterMarkup(){if(!page.filters?.length)return '';const st=state();return `<section class="panel filter-panel" aria-label="${esc(page.title)} 조회 조건"><form id="suite-filter-form"><div class="filter-row">${page.filters.map(f=>fieldMarkup(f,st.filters[f.key],'filter')).join('')}<div class="filter-actions">${page.extra?.length?`<button class="suite-button" type="button" data-action="extra-filter" aria-expanded="${st.extra}">${icon('filter')}상세 필터</button>`:''}<button class="suite-button filled" type="submit">조회</button><button class="suite-button quiet" data-action="reset-filter" type="button">초기화</button></div></div>${page.extra?.length?`<div class="more-filters" ${st.extra?'':'hidden'}>${page.extra.map(f=>fieldMarkup(f,st.filters[f.key],'filter')).join('')}</div>`:''}</form>${Object.entries(st.filters).filter(([,v])=>v).length?`<div class="applied-conditions">${[...(page.filters||[]),...(page.extra||[])].filter(f=>st.filters[f.key]).map(f=>`<span>${esc(f.label)}: ${esc(st.filters[f.key]===true?'선택':st.filters[f.key])}</span>`).join('')}</div>`:''}</section>`;}
  function filteredRows(cfg=page){const st=state();let result=[...rowsFor(cfg)];const filters=st.filters;
    result=result.filter(row=>Object.entries(filters).every(([k,v])=>{
      if(!v||v==='전체')return true;
      if(k==='q')return Object.values(row).join(' ').toLowerCase().includes(String(v).toLowerCase());
      if(k==='business')return String(row.business||'').replace(/-/g,'').includes(String(v).replace(/-/g,''));
      if(k==='from'||k==='to'){const d=String(row.date||row.last||row.due||'').slice(0,10);return k==='from'?d>=v:d<=v;}
      if(k==='fromMonth'||k==='toMonth'){const d=row.forecastMonth||'';return k==='fromMonth'?d>=v:d<=v;}
      if(k==='contractFrom'||k==='contractTo'){const d=row.invoiceDate||'';return k==='contractFrom'?d>=v:d<=v;}
      if(k==='range'&&cfg.entity==='tasks'){if(v==='기한 경과')return row.status==='진행'&&row.due?.slice(0,10)<today;if(v==='오늘')return row.due?.slice(0,10)===today&&row.status==='진행';if(v==='7일 내')return row.due?.slice(0,10)>=today&&row.due?.slice(0,10)<='2026-10-09';if(v==='오늘 완료')return row.status==='완료'&&row.completedDate===today;}
      if(k==='range'&&cfg.entity==='sslExpiration'){const d=daysLeft(row.expirationDate);if(v==='만료')return d<0;if(v==='7일 내')return d>=0&&d<=7;if(v==='30일 내')return d>=0&&d<=30;if(v==='90일 내')return d>=0&&d<=90;}
      if(k==='scope'){if(['내 업무','내 리드','내 담당 고객사','개인'].includes(v))return row.owner===owners[0];return true;}
      if(k==='mine')return row.owner===owners[0];
      if(k==='forecastOnly')return data.forecasts.some(f=>f.company===row.company);
      if(k==='product')return String(row.product||row.products||'').includes(v);
      if(k==='year')return String(row.date||'').startsWith(v);
      if(k==='expiration'){const d=daysLeft(row.expirationDate);return v==='만료'?d<0:v==='30일 내 만료'?d>=0&&d<=30:d>30;}
      if(k==='period'){const m=row.forecastMonth||'';return v==='이번 달'?m==='2026-10':v==='최근 3개월'?m>='2026-08'&&m<='2026-10':v==='올해'?m.startsWith('2026'):true;}
      if(['basis','all','sort','inactive','group'].includes(k))return true;
      const current=row[k];return current===undefined?true:String(current).toLowerCase().includes(String(v).toLowerCase());
    }));
    if(st.sort)result.sort((a,b)=>String(columnValue(a,st.sort)).localeCompare(String(columnValue(b,st.sort)),'ko',{numeric:true})*st.direction);
    if(filters.sort==='금액 높은순')result.sort((a,b)=>(b.amount||0)-(a.amount||0));
    if(filters.sort==='고객사명순')result.sort((a,b)=>(a.company||a.name).localeCompare(b.company||b.name,'ko'));
    if(cfg.kind==='forecast'&&st.tab==='이월')result=result.filter(r=>r.carryoverMonth);
    if(cfg.entity==='tasks'&&st.tab!=='전체'){const t=st.tab;if(t==='기한 경과')result=result.filter(r=>r.status==='진행'&&r.due?.slice(0,10)<today);if(t==='오늘')result=result.filter(r=>r.due?.slice(0,10)===today&&r.status==='진행');if(t==='예정')result=result.filter(r=>r.due?.slice(0,10)>today&&r.status==='진행');if(t==='완료')result=result.filter(r=>r.status==='완료');}
    return result;
  }
  function daysLeft(date){return Math.ceil((Date.parse(date||today)-Date.parse(today))/86400000);}
  function plainChart(labels,values,unit='건'){const max=Math.max(1,...values);return `<div class="panel-body"><div class="chart-unit">단위: ${esc(unit)}</div><div class="bar-chart" role="img" aria-label="${esc(labels.map((l,i)=>l+' '+money(values[i])+unit).join(', '))}">${values.map((v,i)=>`<div class="bar-column"><div class="bar-track"><div class="bar ${i===values.length-1?'current':''}" style="height:${v>0?Math.max(3,v/max*95):0}%"><span class="bar-value">${money(v)}</span></div></div><span>${esc(labels[i])}</span></div>`).join('')}</div></div>`;}
  function plainDistribution(rows,field){const entries={};rows.forEach(r=>entries[r[field]||'미등록']=(entries[r[field]||'미등록']||0)+1);const max=Math.max(1,...Object.values(entries));return Object.entries(entries).map(([l,v])=>`<div class="distribution-row"><span>${esc(l)}</span><div class="distribution-track"><div style="width:${v/max*100}%"></div></div><b>${v}</b></div>`).join('')||'<div class="empty-panel">표시할 데이터가 없습니다.</div>';}
  function columnValue(row,col){const map={고객사:row.company||row.name,거래처:row.company||row.name,기관명:row.name,'회사/담당자':row.company||row.name,담당자명:row.name,회사명:row.company,업무:row.name,'대상 고객':row.company,'발주명':row.name,이름:row.name,부서명:row.name,기관유형명:row.name,항목명:row.name,키워드:row.name,품목명:row.name,옵션명:row.name,활동유형명:row.name,'담당자':row.owner,'영업담당자':row.owner,'현재 담당자':row.owner,'새 담당자':state().selected.includes(row.id)?state().transferOwner||'미지정':'—','입력자':row.owner,'영업상태':row.status,'영업진행상태':row.status,'계약여부':row.status,'진행상태':row.status,'출고상태':row.status,'알림상태':row.status,'상태':row.status,'설립단계':row.stage,'리드 단계':row.stage,'리드 점수':row.score,'현재제품':row.products?.join(', ')||row.product,'이전제품':row.previousProducts?.join(', '),'제품':row.products?.join(', ')||row.product,'품목':row.product,'관심 품목':row.product,'SSL 품목':row.product,'발주 품목':row.product||row.items?.map(i=>i.product).join(', '),'사업자등록번호':row.business,'사업자번호':row.business,'고객코드':row.id,'담당자코드':row.id,'건수':row.count,'품목코드':row.code,'옵션코드':row.code,'매입처':row.supplier,'발주번호':row.purchaseId||row.id,'연락처':row.phone,'이메일':row.email,'주소':row.address,'고객사 담당자':row.contact,'메인 담당자':row.primary?'메인':'일반','기관유형':row.institution,'거래처유형':row.clientType,'고객유형':row.clientType,'소스출처':row.source,'유입':row.source,'인입경로':row.channel,'마케팅 채널':row.channel,'팀':row.custom1||row.team,'관리항목2':row.custom2,'관리항목3':row.custom3,'부서':row.department,'직책':row.position,'직급':row.position,'권한':row.role,'담당업무':row.work,'로그인 ID':row.loginId,'퇴사일':row.retirementDate,'재직 상태':row.retirementDate?'퇴사':row.status,'소속 회원':row.count||0,'사용 고객사':row.count||0,'옵션 수':row.count||0,'노출 순서':row.order,'수집 사용':row.enabled?'사용':'중지','연결 기사':row.count||0,'연결 기관':row.type==='고객사 연계 키워드'?1:0,'최근 활동':row.last,'활동일시':row.date,'활동일':row.date,'견적일시':row.date,'유입일시':row.date,'발주일':row.date,'설치일':row.date,'등록일':row.date,'마감일시':row.due,'응답기한':row.due,'만료일':row.expirationDate,'갱신예정일':row.renewalDate,'잔여일':daysLeft(row.expirationDate)+'일','납기예정일':row.deliveryDate,'계약예정일':row.invoiceDate,'포캐스팅 예정월':row.forecastMonth,'설립시기':row.establishmentMonth,'예산편성여부':row.budget,'예산편성시기':row.budgetMonth,'알림주기':row.reminderDays+'일','연계 뉴스':'샘플 2건','계약 형태':row.dealType,'이월원월':row.carryoverMonth,'이월사유':row.carryoverReason,'대체':row.replacedBy||'미지정','우선순위':row.priority,'유형':row.type,'활동 유형':row.type,'활동유형':row.type,'접촉유형':row.type,'세부유형':row.subtype,'상세유형':row.subtype,'활동명':row.name,'제목':row.name,'제목 / 내용':row.name,'문의내용':row.content,'연계 영업활동':row.linkedActivity||'미연계','리드타임':'3일','사용모듈':row.modules,'도메인 용도':row.domain,'인증서번호':row.certificate,'출고 메모':row.content,'만료상태':daysLeft(row.expirationDate)<0?'만료':daysLeft(row.expirationDate)<=30?'30일 내 만료':'유효','알림구간':daysLeft(row.expirationDate)<=7?'7일 내':daysLeft(row.expirationDate)<=30?'30일 내':'정상','갱신주기':row.renewalPeriod,'수량':row.quantity||1,'첨부':row.attachments?.length?row.attachments.length+'개':'없음'};
    if(['라이선스','라이선스 금액'].includes(col))return row.license||0;if(col==='교육비')return row.education||0;if(['견적총액','총액','합계액','출고 금액'].includes(col))return row.amount||Number(row.license||0)+Number(row.education||0);if(col==='공급가액')return Math.round((row.amount||0)/1.1);if(col==='부가세')return (row.amount||0)-Math.round((row.amount||0)/1.1);
    return map[col]??'—';
  }
  function tableMarkup(rows=filteredRows(),cfg=page){const st=state();const all=cfg.columns||['이름','상태'];const visible=st.columns||all.slice(0,Math.min(7,all.length));const total=rows.length;const perPage=8;const maxPage=Math.max(1,Math.ceil(total/perPage));st.page=Math.min(st.page,maxPage);const slice=rows.slice((st.page-1)*perPage,st.page*perPage);const selection=cfg.kind!=='analytics-list';
    return `<section class="panel table-container"><div class="table-toolbar"><div><h2>${esc(cfg.kind==='forecast'?'계약 예정 목록':cfg.admin?'등록 목록':cfg.entity==='tasks'?'업무 목록':'조회 결과')}</h2><span>${total}건</span>${st.selected.length?`<span class="selected-count">${st.selected.length}건 선택</span>`:''}</div><div>${st.selected.length?button('선택 작업','batch-menu','small','check'):''}<div class="column-menu">${button('표시 항목','columns','small','filter')}<div class="column-options" hidden>${all.map(c=>`<label><input type="checkbox" data-column="${esc(c)}" ${visible.includes(c)?'checked':''}>${esc(c)}</label>`).join('')}</div></div>${button('내보내기','export','small','download')}</div></div><div class="table-scroll"><table><thead><tr>${selection?'<th><input class="table-select" type="checkbox" aria-label="현재 페이지 전체 선택" id="table-select-all"></th>':''}${visible.map(c=>`<th><button data-sort-column="${esc(c)}">${esc(c)} ${st.sort===c?(st.direction===1?'↑':'↓'):''}</button></th>`).join('')}<th>상세</th></tr></thead><tbody>${slice.length?slice.map(r=>`<tr class="${st.selected.includes(r.id)?'selected-row':''}">${selection?`<td><input type="checkbox" class="table-select" data-row-check="${esc(r.id)}" aria-label="${esc(r.name||r.company)} 선택" ${st.selected.includes(r.id)?'checked':''}></td>`:''}${visible.map((c,i)=>{let value=columnValue(r,c);const isMoney=['라이선스','교육비','총액','합계액','출고 금액','견적총액','공급가액','부가세'].includes(c);if(isMoney)value=money(value);else if(/일시|활동일|견적일|유입일/.test(c))value=String(value).replace('T',' ');const stateLike=/상태|여부|단계|우선|유입$/.test(c);return `<td>${i===0?`<button class="link-button cell-main" data-open-row="${esc(r.id)}">${esc(value)}</button><span class="cell-sub">${esc(r.id)}</span>`:stateLike?badge(value,cfg.entity):esc(value)}</td>`;}).join('')}<td><button class="icon-control" data-open-row="${esc(r.id)}" aria-label="${esc(r.name||r.company)} 상세 보기">${icon('arrow')}</button></td></tr>`).join(''):`<tr><td colspan="${visible.length+2}"><div class="empty-panel">${icon('search')}<p>조건에 맞는 결과가 없습니다.</p><p>검색어 또는 필터를 변경해주세요.</p></div></td></tr>`}</tbody></table></div><div class="table-pager"><span>${total?((st.page-1)*perPage+1):0}–${Math.min(st.page*perPage,total)} / ${total}건</span><div class="pager-buttons"><button data-table-page="${st.page-1}" ${st.page===1?'disabled':''} aria-label="이전 페이지">‹</button>${Array.from({length:maxPage},(_,i)=>`<button data-table-page="${i+1}" class="${st.page===i+1?'active':''}" aria-label="${i+1}페이지">${i+1}</button>`).join('')}<button data-table-page="${st.page+1}" ${st.page===maxPage?'disabled':''} aria-label="다음 페이지">›</button></div></div></section>`;
  }
  function metrics(items){return `<div class="metric-strip ${page.id==='home'?'dashboard-metrics':''}">${items.map((item,i)=>`<div class="metric-card ${item.class||''}"><div>${esc(item.label)}${icon(item.icon||'chart')}</div><strong>${esc(item.value)}${item.unit?`<small>${esc(item.unit)}</small>`:''}</strong><p>${esc(item.note||'조회 조건 기준 · 샘플 데이터')}</p></div>`).join('')}</div>`;}
  function chart(title,values,labels,unit='건'){if(Array.isArray(title))return plainChart(title,values,labels||'건');const max=Math.max(1,...values);return `<section class="panel"><div class="panel-heading"><div><h2>${esc(title)}</h2><span>조회 조건 기준 · ${esc(unit)}</span></div><span class="count-pill">샘플</span></div><div class="panel-body"><div class="bar-chart" role="img" aria-label="${esc(title+': '+labels.map((l,i)=>l+' '+values[i]+unit).join(', '))}">${values.map((v,i)=>`<div class="bar-column"><div class="bar-track"><div class="bar ${i===values.length-1?'current':''}" style="height:${v>0?Math.max(3,v/max*95):0}%"><span class="bar-value">${esc(v)}</span></div></div><span>${esc(labels[i])}</span></div>`).join('')}</div></div></section>`;}
  function distribution(title,rows,field){if(Array.isArray(title))return plainDistribution(title,rows);const entries={};rows.forEach(r=>entries[r[field]||'미등록']=(entries[r[field]||'미등록']||0)+1);const max=Math.max(1,...Object.values(entries));return `<section class="panel"><div class="panel-heading"><h2>${esc(title)}</h2></div><div class="panel-body">${Object.entries(entries).map(([label,value])=>`<div class="distribution-row"><span>${esc(label)}</span><div class="distribution-track"><div style="width:${value/max*100}%"></div></div><b>${value}</b></div>`).join('')||'<div class="empty-panel">표시할 데이터가 없습니다.</div>'}</div></section>`;}
  function analyticsTop(rows){return metrics([{label:'조회 내역',value:rows.length,unit:'건',icon:'activity'},{label:'고객사',value:new Set(rows.map(r=>r.company)).size,unit:'개',icon:'users'},{label:'담당자',value:new Set(rows.map(r=>r.owner)).size,unit:'명',icon:'users'},{label:page.entity==='quotes'?'견적 총액':'등록 금액',value:Math.round(rows.reduce((sum,r)=>sum+(r.amount||0),0)/10000).toLocaleString(),unit:'만원',class:'active'}])+`<div class="charts-grid">${chart(page.entity==='quotes'?'월별 견적 추이':'활동 추이',['05','06','07','08','09','10'].map(m=>rows.filter(r=>(r.date||'').slice(5,7)===m).length),['5월','6월','7월','8월','9월','10월'])}${distribution('유형별 구성',rows,'type')}</div>`;}
  function renderNavigation(){const admin=page.admin||page.id==='admin';const groups=admin?['관리자','계정 · 조직','기준정보','운영 설정']:['워크스페이스','고객 관리','영업 실행','분석 · 보고','SSL · 계약','포캐스팅'];$('suite-navigation').innerHTML=groups.map(group=>{let members=pages.filter(p=>p.group===group&&(admin?p.admin||p.id==='admin':!p.admin));return `<div class="nav-section">${group==='워크스페이스'||group==='관리자'?'':`<div class="nav-section-title">${esc(group)}</div>`}${members.map(p=>`<a class="nav-link ${pageId===p.id?'current':''}" href="#${p.id}" ${pageId===p.id?'aria-current="page"':''}>${icon(p.icon||(p.admin?'settings':'file'))}<span>${esc(p.title)}</span>${p.id==='tasks'?`<span class="nav-count">${data.tasks.filter(t=>t.status==='진행').length}</span>`:''}</a>`).join('')}</div>`;}).join('')+(admin?`<div class="nav-section"><a class="nav-link" href="#home">${icon('arrow')}영업 워크스페이스로 돌아가기</a></div>`:'');$('topbar-breadcrumb').innerHTML=`<span>${esc(admin?'관리자':'CRM')}</span><span>/</span><span>${esc(page.group)}</span><span>/</span><strong>${esc(page.title)}</strong>`;}
  function render(){page=pages.find(p=>p.id===pageId)||pages[0];pageId=page.id;renderNavigation();document.title=page.title+' · IONE CRM 리뉴얼 시안';const main=$('suite-main');let html='';
    const primary=page.primary?button(page.primary,'create','filled','plus'):'';
    if(page.kind==='activity'){syncLegacy();const company=new URLSearchParams(location.hash.split('?')[1]||'').get('customer');html=`<div class="activity-host"><iframe id="activity-frame" src="activity.html?v=4.3&embedded=1${company?'&customer='+encodeURIComponent(company):''}" title="영업활동 관리 시안"></iframe></div>`;}
    else if(page.kind==='home')html=homeView();
    else if(page.kind==='list'||page.kind==='analytics-list'){const rows=filteredRows();html=pageHeader(primary)+filterMarkup()+(page.kind==='analytics-list'?analyticsTop(rows):page.id==='leads'?leadMetrics():page.id==='ssl-expiration'?sslMetrics():page.id==='contacts'?contactSummary():'')+tableMarkup(rows);}
    else if(page.kind==='tasks')html=tasksView();
    else if(page.kind==='forecast')html=forecastView();
    else if(page.kind==='form')html=formView();
    else if(page.kind==='news')html=newsView();
    else if(page.kind==='ai')html=aiView();
    else if(page.kind==='work-report')html=workReportView();
    else if(page.kind==='report-builder')html=reportBuilderView();
    else if(page.kind==='upload'){importState=state().import||(state().import={step:1,rows:[],fileName:'',mode:'신규추가 + 기존업데이트',match:'사업자번호',selectedColumns:page.id==='options-upload'?['품목','옵션명','옵션코드']:['고객사명','사업자번호','영업담당자']});html=uploadView();}
    else if(page.kind==='master')html=masterView();
    else if(page.kind==='admin')html=adminView();
    else if(page.kind==='transfer')html=transferView();
    else if(page.kind==='permissions')html=permissionsView();
    else if(page.kind==='goals')html=goalsView();
    else if(page.kind==='manage-items')html=manageItemsView();
    else if(page.kind==='work-settings')html=workSettingsView();
    else if(page.kind==='settings')html=settingsView();
    else if(page.kind==='migration')html=migrationView();
    else if(page.kind==='login')html=loginView();
    main.innerHTML=html;bindMain();
  }
  function go(id){if(location.hash.slice(1)===id){pageId=id.split('?')[0];render();}else location.hash=id;}
  function readFilter(form){const all=[...(page.filters||[]),...(page.extra||[])];const fd=new FormData(form);const result={};all.forEach(f=>{result[f.key]=f.type==='checkbox'?form.elements[f.key]?.checked:fd.get(f.key)||'';});return result;}
  function bindMain(){const main=$('suite-main');main.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>handleAction(b.dataset.action,b)));main.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.route)));main.querySelectorAll('[data-open-row]').forEach(b=>b.addEventListener('click',()=>openRow(b.dataset.openRow)));main.querySelectorAll('[data-sort-column]').forEach(b=>b.addEventListener('click',()=>{const st=state();st.direction=st.sort===b.dataset.sortColumn?-st.direction:1;st.sort=b.dataset.sortColumn;render();}));main.querySelectorAll('[data-table-page]').forEach(b=>b.addEventListener('click',()=>{state().page=Number(b.dataset.tablePage);render();}));main.querySelectorAll('[data-row-check]').forEach(input=>input.addEventListener('change',()=>{const st=state();st.selected=input.checked?[...new Set([...st.selected,input.dataset.rowCheck])]:st.selected.filter(id=>id!==input.dataset.rowCheck);render();}));if($('table-select-all')){$('table-select-all').checked=filteredRows().slice((state().page-1)*8,state().page*8).every(r=>state().selected.includes(r.id))&&filteredRows().length>0;$('table-select-all').addEventListener('change',event=>{const list=filteredRows().slice((state().page-1)*8,state().page*8).map(r=>r.id);state().selected=event.target.checked?[...new Set([...state().selected,...list])]:state().selected.filter(id=>!list.includes(id));render();});}
    main.querySelectorAll('[data-column]').forEach(input=>input.addEventListener('change',()=>{const current=state().columns||page.columns.slice(0,7);const cols=input.checked?[...current,input.dataset.column]:current.filter(c=>c!==input.dataset.column);if(!cols.length){input.checked=true;return;}state().columns=page.columns.filter(c=>cols.includes(c));render();}));
    const filter=$('suite-filter-form');if(filter)filter.addEventListener('submit',event=>{event.preventDefault();const filters=readFilter(filter);if(filters.from&&filters.to&&filters.from>filters.to){notify('종료일을 시작일 이후로 선택해주세요.');return;}state().filters=filters;state().page=1;state().selected=[];render();});
    main.querySelectorAll('[data-task-complete]').forEach(b=>b.addEventListener('click',()=>completeTask(b.dataset.taskComplete)));
    main.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{state().tab=b.dataset.tab;state().page=1;state().selected=[];render();}));
    main.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{state().view=b.dataset.view;render();}));
    main.querySelectorAll('[data-home-range]').forEach(b=>b.addEventListener('click',()=>{state().homeRange=b.dataset.homeRange;render();}));
    bindSpecials(main);
  }
  function handleAction(action,buttonElement){
    if(action==='extra-filter'){state().extra=!state().extra;const more=$('suite-filter-form').querySelector('.more-filters');more.hidden=!state().extra;buttonElement.setAttribute('aria-expanded',String(state().extra));}
    else if(action==='reset-filter'){state().filters={};state().page=1;state().selected=[];render();}
    else if(action==='columns'){const options=buttonElement.parentElement.querySelector('.column-options');options.hidden=!options.hidden;}
    else if(action==='create'){if(page.id==='ssl-expiration'){openRow((filteredRows()[0]||rowsFor()[0])?.id);return;}if(page.id==='members'){manageDuties();return;}showEntityForm(page);}
    else if(action==='export'){exportRows(filteredRows(),page.columns||['이름','상태'],page.title);}
    else if(action==='batch-menu')batchActions();
    else specialAction(action,buttonElement);
  }
  function exportRows(rows,columns,fileName){const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const safe=v=>/^[=+\-@]/.test(String(v))?"'"+v:v;const csv='\uFEFF'+[columns.map(quote).join(','),...rows.map(r=>columns.map(c=>quote(safe(columnValue(r,c)))).join(','))].join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),fileName+'-시안.csv');notify('샘플 조회 결과를 CSV로 내보냈어요.');}
  function downloadBlob(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function openDrawer(title,eyebrow,content){drawerReturnFocus=document.activeElement;$('drawer-title').textContent=title;$('drawer-eyebrow').textContent=eyebrow;$('drawer-content').innerHTML=content;$('suite-drawer').hidden=false;$('drawer-backdrop').hidden=false;document.querySelector('.app-frame').inert=true;$('app-sidebar').inert=true;$('close-drawer').focus();}
  function closeDrawer(){$('suite-drawer').hidden=true;$('drawer-backdrop').hidden=true;document.querySelector('.app-frame').inert=false;$('app-sidebar').inert=false;if(drawerReturnFocus?.isConnected)drawerReturnFocus.focus();}
  function openRow(id,cfg=page){const row=rowsFor(cfg).find(r=>r.id===id);if(!row)return;const columns=cfg.columns||['이름','상태'];const customerName=row.company||row.name;let html=`<div class="drawer-section"><div style="display:flex;justify-content:space-between;align-items:center"><h3>기본 정보</h3>${badge(row.status||'등록',cfg.entity)}</div><dl class="detail-grid">${columns.map(col=>`<div class="${/내용|주소|사유/.test(col)?'full':''}"><dt>${esc(col)}</dt><dd>${esc(/라이선스|금액|총액|교육비|합계/.test(col)?money(columnValue(row,col)):String(columnValue(row,col)).replace('T',' '))}</dd></div>`).join('')}</dl></div>`;
    if(row.content)html+=`<div class="drawer-section"><h3>상담 · 메모</h3><p style="font-size:12px;color:#8596af;line-height:1.9;white-space:pre-wrap">${esc(row.content)}</p></div>`;
    const related=data.activities.filter(a=>a.company===customerName).slice(0,3);if(related.length)html+=`<div class="drawer-section"><h3>연결된 영업활동</h3><div class="drawer-timeline">${related.map(a=>`<div><time>${esc(a.date.replace('T',' '))}</time><strong>${esc(a.name)}</strong><p>${esc(a.type+' · '+a.owner)}</p></div>`).join('')}</div></div>`;
    html+=`<div class="drawer-actions">${cfg.form?`<button class="suite-button filled" id="drawer-edit">${icon('file')}정보 수정</button>`:''}<button class="suite-button" id="drawer-activity">${icon('activity')}활동 기록</button>${cfg.entity==='tasks'?'<button class="suite-button soft" id="drawer-complete">완료 처리</button><button class="suite-button" id="drawer-postpone">기한 연기</button>':''}${cfg.entity==='leads'?'<button class="suite-button soft" id="drawer-lead-task">첫 연락 업무 만들기</button>':''}${cfg.entity==='contacts'?'<button class="suite-button" id="drawer-move">이직 등록</button><button class="suite-button" id="drawer-leave">퇴사 등록</button><button class="suite-button" id="drawer-contact-mail">메일 후속관리</button>':''}${cfg.kind==='forecast'?'<button class="suite-button soft" id="drawer-carryover">이월 처리</button>':''}${cfg.entity==='sslExpiration'?'<button class="suite-button filled" id="drawer-renew">갱신 처리</button><button class="suite-button" id="drawer-ack">알림 확인</button>':''}${cfg.entity==='sslDelivery'?'<button class="suite-button" id="drawer-return">반품</button>':''}${['products','productOptions'].includes(cfg.entity)?'<button class="suite-button" id="drawer-deactivate">활성 상태 변경</button>':''}</div>`;
    openDrawer(row.name||row.company,cfg.title+' · '+row.id,html);
    const bind=(id,fn)=>{if($(id))$(id).addEventListener('click',fn);};
    bind('drawer-edit',()=>{closeDrawer();showEntityForm(cfg,row);});
    bind('drawer-activity',()=>{const c=data.customers.find(c=>c.name===customerName);closeDrawer();go('activity'+(c?'?customer='+encodeURIComponent(c.id):''));});
    bind('drawer-complete',()=>{closeDrawer();completeTask(row.id);});
    bind('drawer-postpone',()=>{closeDrawer();showEntityForm({...cfg,title:'기한 연기',form:[{title:'새 일정',fields:[{key:'due',label:'마감일시',type:'datetime-local',required:true},{key:'content',label:'연기 사유',type:'textarea'}]}]},row);});
    bind('drawer-lead-task',()=>{closeDrawer();const taskCfg=pages.find(p=>p.id==='tasks');showEntityForm(taskCfg,{name:row.company+' 첫 연락',company:row.company,owner:row.owner,content:row.content,due:today+'T17:00'});});
    bind('drawer-move',()=>{closeDrawer();showEntityForm({...cfg,title:'이직 등록',form:[{title:'새 소속',fields:[{key:'company',label:'새 회사명',type:'text',required:true},{key:'department',label:'부서',type:'text'},{key:'position',label:'직책',type:'text'}]}]},row);});
    bind('drawer-leave',()=>{row.status='퇴사';row.retirementDate=today;save();closeDrawer();render();notify('시안에 퇴사 상태를 기록했어요.');});
    bind('drawer-contact-mail',()=>{closeDrawer();showEntityForm({...cfg,title:'메일 후속관리',form:[{title:'메일 · 일정',fields:[{key:'mailSubject',label:'메일 제목',type:'text',required:true},{key:'mailBody',label:'메일 본문',type:'textarea',required:true},{key:'recurrence',label:'반복',type:'select',options:['매주','매월','직접 설정']},{key:'customDays',label:'반복 일수',type:'number'},{key:'nextDate',label:'다음 발송일',type:'date'},{key:'enabled',label:'정기 발송 사용',type:'checkbox'}]}]},row);});
    bind('drawer-carryover',()=>{closeDrawer();showEntityForm({...cfg,title:'이월 처리',form:[{title:'이월 정보',fields:[{key:'carryoverMonth',label:'이월 대상월',type:'month',required:true},{key:'carryoverReason',label:'이월 사유',type:'textarea',required:true}]}]},row);});
    bind('drawer-renew',()=>{closeDrawer();showEntityForm({...cfg,title:'SSL 갱신',form:[{title:'갱신 정보',fields:[{key:'renewalDate',label:'실제 갱신일',type:'date',required:true},{key:'expirationDate',label:'새 만료일',type:'date',required:true},{key:'certificate',label:'인증서번호',type:'text'}]}]},row);});
    bind('drawer-ack',()=>{row.status='확인';save();closeDrawer();render();notify('시안에서 알림을 확인했어요.');});
    bind('drawer-return',()=>{row.status='반품';save();closeDrawer();render();notify('시안에서 반품 상태로 변경했어요.');});
    bind('drawer-deactivate',()=>{row.status=row.status==='활성'?'비활성':'활성';save();closeDrawer();render();notify('시안의 활성 상태를 변경했어요.');});
  }
  function formFields(cfg,row={}){return (cfg.form||[]).map((group,i)=>`<section class="form-section"><h3><span class="step-number">${String(i+1).padStart(2,'0')}</span>${esc(group.title)}</h3><div class="form-grid">${group.fields.map(f=>fieldMarkup(f,row[f.key]??(f.type==='date'&&(f.required||f.key==='date')?today:f.type==='datetime-local'?today+'T10:30':''),'entity')).join('')}</div>${group.fields.some(f=>f.key==='license')?`<div class="money-summary"><span>견적 총액 · 라이선스 + 교육비</span><strong id="live-money">${money(Number(row.license||0)+Number(row.education||0))}<small style="font-size:12px"> 원</small></strong></div>`:''}</section>`).join('');}
  function showEntityForm(cfg,row={}){editing={cfg,id:row.id||null};$('edit-title').textContent=row.id?cfg.title+' 수정':cfg.title+' 등록';$('edit-eyebrow').textContent=groupName(cfg);$('edit-fields').innerHTML=formFields(cfg,row);$('edit-note').textContent='시안의 샘플 데이터에만 저장됩니다.';$('edit-dialog').showModal();bindFormInputs($('entity-form'));}
  function formValue(form,cfg){const fd=new FormData(form);const result={};(cfg.form||[]).flatMap(g=>g.fields).forEach(f=>{if(f.type==='multi')result[f.key]=fd.getAll(f.key);else if(f.type==='checkbox')result[f.key]=form.elements[f.key]?.checked||false;else if(f.type==='number')result[f.key]=Number(fd.get(f.key)||0);else if(f.type==='file')result[f.key]=[...form.elements[f.key].files].map(file=>({name:file.name,size:file.size}));else if(f.type==='line-items')result[f.key]=readLineItems(form);else result[f.key]=String(fd.get(f.key)||'').trim();});return result;}
  function storeEntity(cfg,value,id){if(!data[cfg.entity])data[cfg.entity]=[];if(value.newCompany&&value.customerType==='신규 고객')value.company=value.newCompany;if('license'in value||'education'in value)value.amount=Number(value.license||0)+Number(value.education||0);if(value.products?.length)value.product=value.products[0];if(value.items?.length)value.amount=value.items.reduce((sum,item)=>sum+item.quantity*item.unitPrice*1.1,0);const existing=id?data[cfg.entity].find(r=>r.id===id):null;
    if(existing)Object.assign(existing,value);else{value.id=cfg.entity.toUpperCase()+'-'+Date.now();if(!value.name)value.name=value.company||value.product||cfg.title;if(!value.status)value.status=cfg.entity==='tasks'?'진행':cfg.entity==='leads'?'신규':cfg.entity==='customers'?'미진행':'사용';if(cfg.entity==='customers'){value.last=today;value.note='첫 활동을 기록해주세요';if(!value.business)value.business='000-00-00000';}data[cfg.entity].unshift(value);}save();return existing||value;}
  function bindFormInputs(form){form.querySelectorAll('.multi-options input').forEach(input=>input.addEventListener('change',()=>{const field=input.closest('.multi-field');const selected=[...field.querySelectorAll('input:checked')].map(i=>i.value);field.querySelector('summary span').textContent=selected.join(', ')||'품목을 선택하세요';}));form.addEventListener('input',()=>{const license=Number(form.elements.license?.value||0),edu=Number(form.elements.education?.value||0);const total=form.querySelector('#live-money');if(total)total.innerHTML=money(license+edu)+'<small style="font-size:12px"> 원</small>';updateLineTotals(form);});form.querySelectorAll('[data-add-line]').forEach(b=>b.addEventListener('click',()=>{form.querySelector('.line-items tbody').insertAdjacentHTML('beforeend',lineItemRow());bindLineRemovals(form);updateLineTotals(form);}));bindLineRemovals(form);updateLineTotals(form);}
  function formView(){return pageHeader(button('현황 보기','form-list','','chart'))+`<section class="panel form-panel"><form id="page-entity-form">${formFields(page,state().draft||{})}<div class="form-actions"><span>필수 항목을 확인하고 저장해주세요.</span><div><button class="suite-button" type="reset">초기화</button><button class="suite-button filled" type="submit">${icon('check')}저장</button></div></div></form></section>`;}
  function lineItemRow(value={}){return `<tr><td><select name="line-product" aria-label="SSL 품목">${['SSL DV 인증서','SSL OV 인증서','SSL Wildcard 인증서'].map(p=>`<option ${value.product===p?'selected':''}>${p}</option>`).join('')}</select></td><td><select name="line-company" aria-label="발주 고객사">${data.customers.map(c=>`<option ${value.company===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></td><td><select name="line-renewal" aria-label="갱신주기"><option>1년</option><option>2년</option><option>3년</option></select></td><td><input name="line-domain" aria-label="도메인 용도" value="${esc(value.domain||'')}" placeholder="도메인 / 용도"></td><td><input name="line-qty" aria-label="품목 수량" type="number" min="1" value="${value.quantity||1}"></td><td><input name="line-unit" aria-label="품목 매입단가" type="number" min="0" value="${value.unitPrice??200000}"></td><td class="line-total">${money((value.quantity||1)*(value.unitPrice??200000)*1.1)}</td><td><button type="button" class="icon-control" data-remove-line aria-label="품목 행 삭제">${icon('close')}</button></td></tr>`;}
  function lineItems(value){return `<div class="line-items"><table><thead><tr><th>SSL 품목</th><th>고객사</th><th>갱신주기</th><th>도메인 용도</th><th>수량</th><th>매입단가</th><th>합계 · 부가세 포함</th><th></th></tr></thead><tbody>${(Array.isArray(value)&&value.length?value:[{}]).map(lineItemRow).join('')}</tbody></table><div style="padding:12px 0;display:flex;justify-content:space-between">${button('행 추가','unused','small','plus').replace('data-action="unused"','data-add-line')}<span class="line-order-total">합계 ${money(220000)}원</span></div></div>`;}
  function bindLineRemovals(form){form.querySelectorAll('[data-remove-line]').forEach(b=>{b.onclick=()=>{const tbody=b.closest('tbody');if(tbody.children.length===1){notify('발주 품목을 한 개 이상 입력해주세요.');return;}b.closest('tr').remove();updateLineTotals(form);};});}
  function readLineItems(form){return [...form.querySelectorAll('.line-items tbody tr')].map(tr=>({product:tr.querySelector('[name=line-product]').value,company:tr.querySelector('[name=line-company]').value,renewalPeriod:tr.querySelector('[name=line-renewal]').value,domain:tr.querySelector('[name=line-domain]').value,quantity:Number(tr.querySelector('[name=line-qty]').value),unitPrice:Number(tr.querySelector('[name=line-unit]').value)}));}
  function updateLineTotals(form){let total=0;form.querySelectorAll('.line-items tbody tr').forEach(tr=>{const subtotal=Number(tr.querySelector('[name=line-qty]').value)*Number(tr.querySelector('[name=line-unit]').value)*1.1;total+=subtotal;tr.querySelector('.line-total').textContent=money(subtotal);});const out=form.querySelector('.line-order-total');if(out)out.textContent='합계 '+money(total)+'원';}
  function completeTask(id){const row=data.tasks.find(t=>t.id===id);if(!row)return;row.status=row.status==='완료'?'진행':'완료';row.completedDate=row.status==='완료'?today:'';save();render();notify(row.status==='완료'?'시안에서 업무를 완료했어요.':'시안에서 진행 중으로 되돌렸어요.');}
  function manageDuties(){openDrawer('회원 담당업무 관리','샘플 조직',`<form id="duties-form"><div class="drawer-section">${data.members.map(m=>`<label style="margin:16px 0">${esc(m.name)}<select name="${m.id}">${['영업','마케팅','운영'].map(t=>`<option ${m.work===t?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}</div><div class="drawer-actions"><button class="suite-button filled" type="submit">시안에 저장</button></div></form>`);$('duties-form').onsubmit=e=>{e.preventDefault();new FormData(e.target).forEach((v,k)=>{const m=data.members.find(m=>m.id===k);if(m)m.work=v;});save();closeDrawer();render();notify('샘플 담당업무를 저장했어요.');};}
  function batchActions(){const selected=rowsFor().filter(r=>state().selected.includes(r.id));if(!selected.length)return;if(page.id==='transfer'){specialAction('transfer-apply');return;}const statusField=(page.form||[]).flatMap(g=>g.fields).find(f=>f.key==='status');const choices=statusField?.options||({contacts:['재직','퇴사'],members:['재직','퇴사'],sslPurchase:['발주','입고','취소'],sslExpiration:['미확인','확인']}[page.entity])||['사용','중지'];openDrawer('선택한 '+selected.length+'건','일괄 작업',`<div class="drawer-section"><p>${selected.map(r=>esc(r.name||r.company)).join('<br>')}</p></div><div class="drawer-section"><label>변경 상태<select id="batch-status">${choices.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><div class="drawer-actions"><button class="suite-button filled" id="apply-batch">시안에 적용</button></div>`);$('apply-batch').addEventListener('click',()=>{selected.forEach(r=>{r.status=$('batch-status').value;if(page.entity==='members'||page.entity==='contacts')r.retirementDate=r.status==='퇴사'?today:'';});state().selected=[];save();closeDrawer();render();notify('선택한 샘플 데이터에 적용했어요.');});}
  function tabs(items){return `<div class="section-tabs" role="group" aria-label="콘텐츠 필터">${items.map(t=>`<button data-tab="${esc(t)}" aria-pressed="${state().tab===t}" class="${state().tab===t?'active':''}">${esc(t)}</button>`).join('')}</div>`;}
  function withContentTabs(content,controls){
    const header=`<div class="panel-tabs">${controls}</div>`;
    const opening=content.match(/<section class="panel(?: [^"]*)?"[^>]*>/);
    if(opening)return content.replace(opening[0],opening[0]+header);
    return `<section class="panel tabbed-panel">${header}<div class="tabbed-content">${content}</div></section>`;
  }
  function routeLink(id,label,cls='suite-button'){return `<button type="button" class="${cls}" data-route="${id}">${esc(label)}${icon('arrow')}</button>`;}
  function taskCards(rows){return rows.length?rows.map(t=>`<div class="task-preview"><button class="task-check ${t.status==='완료'?'done':''}" data-task-complete="${t.id}" aria-label="${esc(t.name)} ${t.status==='완료'?'완료 취소':'완료'}">${t.status==='완료'?icon('check'):''}</button><div><button class="cell-main" data-open-row="${t.id}">${esc(t.name)}</button><span>${esc(t.company)} · ${esc(t.due.replace('T',' '))}</span></div>${badge(t.priority,'priority')}</div>`).join(''):'<div class="empty-panel">이 기간에 남은 업무가 없어요.</div>';}
  function homeView(){const f=state().filters;const scoped=data.tasks.filter(t=>f.scope!=='개인'||t.owner===owners[0]);const range=state().homeRange||'오늘';const clientCandidates=data.customers.filter(c=>(!f.status||c.status===f.status)&&(!f.clientType||c.clientType===f.clientType)&&(!f.product||String(c.products||c.product).includes(f.product))&&(!f.inactive||daysLeft(c.last)<=-Number(f.inactive.split('일')[0])));const tasks=scoped.filter(t=>range==='완료'?t.status==='완료':t.status!=='완료'&&(range==='이번 주'?t.due.slice(0,10)<='2026-10-09':t.due.slice(0,10)<=today));const fc=data.forecasts.filter(r=>r.forecastMonth==='2026-10'&&(f.scope!=='개인'||r.owner===owners[0]));return pageHeader(button('활동 기록','new-activity','filled','plus'))+filterMarkup()+metrics([{label:'오늘 확인할 업무',value:tasks.length+'건',note:'기한 경과 포함',attention:true},{label:'새로운 리드',value:data.leads.filter(r=>r.status==='신규').length+'건',note:'첫 연락이 필요한 고객'},{label:'10월 예상 계약',value:money(fc.reduce((s,r)=>s+r.amount,0))+'원',note:fc.length+'건 · 샘플 계약'},{label:'SSL 만료 예정',value:data.sslExpiration.filter(r=>daysLeft(r.expirationDate)<=30).length+'건',note:'30일 안에 갱신 확인'}])+`<div class="home-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">MY NEXT ACTION</span><h2>오늘의 할 일</h2></div>${routeLink('tasks','업무함 전체')}</div><div class="day-tabs">${['오늘','이번 주','완료'].map(r=>`<button data-home-range="${r}" class="${range===r?'active':''}">${r}</button>`).join('')}</div><div class="panel-body">${taskCards(tasks.slice(0,4))}</div><div class="panel-note">업무를 완료하면 목록과 고객의 후속 기록에 반영됩니다.</div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SALES BRIEFING</span><h2>다음 대화를 준비하세요</h2></div>${badge('샘플 분석')}</div><div class="panel-body">${clientCandidates.slice(0,3).map((c,i)=>`<button class="recommendation" data-customer-detail="${c.id}"><span class="recommendation-index">0${i+1}</span><div><strong>${esc(c.name)}</strong><span>${esc(c.note)} · ${esc(c.owner)}</span></div>${icon('arrow')}</button>`).join('')}</div><div class="panel-note">${routeLink('ai','IONE AI 브리핑 자세히')}</div></section></div><div class="quick-links">${[['customers','고객사 관리','고객 정보와 대화 이력','users'],['leads','새 리드 확인','문의에서 첫 연락까지','users'],['forecast-status','계약 예상 보기','예정 · 이월 · 달성 현황','chart'],['work-report','업무일지 작성','오늘의 실행을 기록','file']].map(([id,t,d,i])=>`<button class="quick-link" data-route="${id}">${icon(i)}<div><strong>${t}</strong><span>${d}</span></div>${icon('arrow')}</button>`).join('')}</div><div class="charts-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">PIPELINE OVERVIEW</span><h2>월별 예상 계약</h2></div>${routeLink('forecast-status','상세 현황')}</div>${chart(['10월','11월','12월'],[0,1,2].map(i=>data.forecasts.filter(r=>r.forecastMonth===['2026-10','2026-11','2026-12'][i]).reduce((s,r)=>s+r.amount,0)/10000),'만원')}</section><section class="panel"><div class="panel-heading"><h2>고객 진행 현황</h2>${routeLink('customers','고객 목록')}</div><div class="panel-body">${distribution(data.customers,'status')}</div></section></div>`;}
  function leadMetrics(){const r=filteredRows();return metrics(['신규','접촉','유효','전환'].map(status=>({label:status+' 리드',value:r.filter(l=>l.status===status).length+'건',note:status==='신규'?'첫 연락 대기':'진행 단계별 현황'})));}
