  function tasksView(){const rows=filteredRows();let content;if(state().view==='보드'){content=`<div class="board-grid">${['진행','완료','취소'].map(status=>`<section class="board-column"><h3>${badge(status,'tasks')} <span>${rows.filter(t=>t.status===status).length}</span></h3>${rows.filter(t=>t.status===status).map(t=>`<button class="board-card" data-open-row="${t.id}">${badge(t.priority,'priority')}<strong>${esc(t.name)}</strong><span>${esc(t.company)}</span><small>${esc(t.due.replace('T',' '))}</small></button>`).join('')}</section>`).join('')}</div>`;}else if(state().view==='달력'){const offset=4;content=`<section class="panel"><div class="calendar-toolbar"><h2>2026년 10월</h2><span>마감일을 클릭해 업무 상세를 확인하세요.</span></div><div class="calendar-grid">${['일','월','화','수','목','금','토'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${Array.from({length:35},(_,i)=>{const d=i-offset+1;return d<1||d>31?'<div class="calendar-day blank"></div>':`<div class="calendar-day ${d===2?'current':''}"><span>${d}</span>${rows.filter(t=>t.due.slice(0,10)==='2026-10-'+String(d).padStart(2,'0')).map(t=>`<button class="calendar-event" data-open-row="${t.id}">${esc(t.name)}</button>`).join('')}</div>`;}).join('')}</div></section>`;}else content=tableMarkup(rows);return pageHeader(button('새 업무','create','filled','plus'))+filterMarkup()+metrics([{label:'기한 경과',value:data.tasks.filter(t=>t.status==='진행'&&t.due.slice(0,10)<today).length+'건',attention:true},{label:'오늘 할 일',value:data.tasks.filter(t=>t.status==='진행'&&t.due.slice(0,10)===today).length+'건'},{label:'완료',value:data.tasks.filter(t=>t.status==='완료').length+'건'}])+withContentTabs(content,`${tabs(['전체','기한 경과','오늘','예정','완료'])}<div class="view-switch" role="group" aria-label="업무 보기 방식">${['목록','보드','달력'].map(v=>`<button class="suite-button small ${state().view===v?'soft':''}" data-view="${v}" aria-pressed="${state().view===v}">${v}</button>`).join('')}</div>`);}
  function forecastView(){const rows=filteredRows();const sum=k=>rows.reduce((s,r)=>s+Number(r[k]||0),0);const contracted=rows.filter(r=>r.status==='계약');return pageHeader(button(page.primary,'create','filled','plus'))+filterMarkup()+metrics([{label:'예상 계약 총액',value:money(sum('amount'))+'원',note:rows.length+'건'},{label:'계약 완료',value:money(contracted.reduce((s,r)=>s+r.amount,0))+'원',note:contracted.length+'건'},{label:'이월 대상',value:rows.filter(r=>r.carryoverMonth).length+'건',attention:true},{label:'계약 전환율',value:(rows.length?Math.round(contracted.length/rows.length*100):0)+'%',note:'조회 대상 기준'}])+withContentTabs((state().tab==='달성 현황'?`<section class="panel"><div class="panel-heading"><h2>담당자별 계약 현황</h2>${routeLink('goals','목표 관리')}</div>${chart(owners,owners.map(o=>rows.filter(r=>r.owner===o&&r.status==='계약').reduce((s,r)=>s+r.amount,0)/10000),'만원')}<div class="panel-note">달성 금액은 계약 상태인 샘플 건을 합산합니다.</div></section>`:tableMarkup(rows)),tabs(['전체','이월','달성 현황']));}
