  function newsView(){const f=state().filters;const rows=sampleNews.filter(n=>(!f.q||(n.title+n.company+n.content).includes(f.q))&&(!f.source||f.source===n.source)&&(!f.important||n.important)&&(!f.unread||!settings['read-'+n.id])&&(!f.from||n.date>=f.from)&&(!f.to||n.date<=f.to)&&(!f.company||n.company===f.company));return pageHeader(button('샘플 기사 새로 확인','news-refresh','','clock'))+filterMarkup()+withContentTabs(`<div class="news-grid"><section class="panel"><div class="panel-heading"><h2>고객과 연결된 소식 <span class="cell-sub">${rows.length}건</span></h2>${badge('샘플 기사')}</div>${rows.filter(n=>state().tab!=='관심 기사'||settings['star-'+n.id]).map(n=>`<article class="news-row"><div class="news-meta"><span>${esc(n.source)} · ${n.date}</span>${badge(n.tag)}</div><h3><button data-news="${n.id}">${esc(n.title)}</button></h3><p>${esc(n.content)}</p><div class="news-row-footer"><span>${esc(n.company)}</span><button class="suite-button small ${settings['star-'+n.id]?'soft':''}" data-news-star="${n.id}">${settings['star-'+n.id]?'관심 등록됨':'관심 등록'}</button></div></article>`).join('')||'<div class="empty-panel">조건에 맞는 기사가 없어요.</div>'}</section><aside class="panel"><div class="panel-heading"><h2>기사에서 실행으로</h2></div><div class="panel-body"><p style="font-size:13px;line-height:1.9;color:#65758b">뉴스 상세에서 고객 정보를 확인하고 후속 업무를 만들어보세요.</p><div class="button-group" style="margin-top:20px">${routeLink('nonprofits','기관 일정 확인')}${routeLink('tasks','후속 업무 확인')}</div></div><div class="panel-note">실제 뉴스 수집 서비스는 연결되어 있지 않습니다.</div></aside></div>`,tabs(['전체','관심 기사']));}
  function aiView(){return pageHeader(button('샘플 브리핑 갱신','ai-refresh','','spark'))+filterMarkup()+`<section class="ai-feature"><span class="eyebrow">IONE INTELLIGENCE · SAMPLE</span><h2>대화가 필요한 고객부터,<br>다음 행동으로 이어지는 브리핑</h2><p>상담 간격 · 계약 예정 · 후속 업무를 함께 확인하세요.</p><div>${badge('2026.10.02 기준')}${badge('샘플 기록 기반')}</div></section><div class="charts-grid"><section class="panel"><div class="panel-heading"><h2>우선 확인할 고객</h2></div><div class="panel-body">${data.customers.slice(0,4).map((c,i)=>`<div class="insight-row"><span class="insight-icon">${icon(i%2?'clock':'spark')}</span><div><strong>${esc(c.name)}</strong><p>${esc(c.note)} · 다음 상담을 준비하세요.</p><button class="suite-button small" data-customer-detail="${c.id}">근거 기록 확인</button></div><button class="suite-button soft small" data-new-task-customer="${c.id}">후속 업무</button></div>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>이번 주 실행 체크</h2></div><div class="panel-body">${distribution(data.tasks,'status')}<div class="button-group" style="margin-top:25px">${routeLink('tasks','내 업무 확인')}${routeLink('forecast-status','예상 계약 확인')}</div></div><div class="panel-note">시안에서 브리핑은 미리 구성한 샘플입니다. 실제 AI 분석을 실행하지 않습니다.</div></section></div>`;}
